#!/usr/bin/env python3
"""Summarize a transcript .jsonl: turns, tool calls per tool, time range.

Usage: transcript_stats.py FILE.jsonl
"""
import collections
import json
import sys


def summarize(lines):
    turns = collections.Counter()
    tools = collections.Counter()
    stamps = []
    for line in lines:
        try:
            rec = json.loads(line)
        except ValueError:
            continue
        if not isinstance(rec, dict):
            continue
        kind = rec.get("type")
        ts = rec.get("timestamp")
        if isinstance(ts, str):
            stamps.append(ts)
        if kind not in ("user", "assistant"):
            continue
        turns[kind] += 1
        msg = rec.get("message")
        content = msg.get("content") if isinstance(msg, dict) else None
        if kind == "assistant" and isinstance(content, list):
            for block in content:
                if isinstance(block, dict) and block.get("type") == "tool_use":
                    tools[str(block.get("name", "?"))] += 1
    return turns, tools, (min(stamps), max(stamps)) if stamps else None


def main(argv):
    if len(argv) != 2:
        print(__doc__.strip(), file=sys.stderr)
        return 2
    with open(argv[1], encoding="utf-8", errors="replace") as f:
        turns, tools, span = summarize(f)
    print("user turns:      %d" % turns["user"])
    print("assistant turns: %d" % turns["assistant"])
    print("tool calls:")
    for name, n in sorted(tools.items(), key=lambda kv: (-kv[1], kv[0])):
        print("  %-20s %d" % (name, n))
    if not tools:
        print("  (none)")
    print("first timestamp: %s" % (span[0] if span else "-"))
    print("last timestamp:  %s" % (span[1] if span else "-"))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
